  1	<script setup lang="ts">
  2	import { onMounted, ref } from 'vue';
  3	import { apiUrl, ApiError } from '../api';
  4	import { useSession } from '../session';
  5	
  6	type ReviewItem = {
  7	  id: string; title: string; description: string; location: string;
  8	  priceAmount: number | null; currency: string | null; status: string;
  9	  publicationStatus: 'UNPUBLISHED' | 'PUBLISHED';
