 13	};
 14	type ReviewCursor = { createdAt: string; id: string };
 15	type ReviewPage = { items: ReviewItem[]; nextCursor: ReviewCursor | null };
 16	type Audit = { id: string; entityType: string; entityId: string | null; listingId: string | null; action: string; reason: string | null; createdAt: string; actor: { email: string }; targetOwner: { email: string } | null };
 17	const session = useSession();
 18	const queue = ref<ReviewItem[]>([]), audit = ref<Audit[]>([]);
 19	const nextCursor = ref<ReviewCursor | null>(null);
 20	const selectedId = ref(''), reason = ref(''), busy = ref(false), loading = ref(true);
 21	const error = ref(''), notice = ref('');
 22	const selected = () => queue.value.find(item => item.id === selectedId.value);
 23	async function load(append = false) {
 24	  loading.value = true; error.value = '';
 25	  try {
 26	    let path = '/admin/listings/review';
 27	    if (append && nextCursor.value) {
 28	      const params = new URLSearchParams({ afterCreatedAt: nextCursor.value.createdAt, afterId: nextCursor.value.id });
 29	      path += `?${params}`;
 30	    }
 31	    const page = await session.apiRequest<ReviewPage>(path);
 32	    queue.value = append ? [...queue.value, ...page.items] : page.items;
 33	    nextCursor.value = page.nextCursor;
 34	    if (!queue.value.some(item => item.id === selectedId.value)) {
 35	      const nextId = queue.value[0]?.id ?? '';
 36	      if (selectedId.value !== nextId) reason.value = '';
 37	      selectedId.value = nextId;
 38	    }
 39	    audit.value = await session.apiRequest<Audit[]>('/admin/listings/audit?limit=30');
 40	  } catch (e) { error.value = e instanceof Error ? e.message : 'No se pudo cargar la revisión.'; }
 41	  finally { loading.value = false; }
 42	}
 43	async function loadMore() { if (!loading.value && nextCursor.value) await load(true); }
 44	function selectListing(id: string) {
 45	  if (selectedId.value === id) return;
 46	  selectedId.value = id;
 47	  reason.value = '';
 48	  error.value = '';
 49	}
 50	async function review(action: 'approve' | 'reject') {
 51	  const item = selected(); if (!item || busy.value) return;
 52	  if (action === 'reject' && reason.value.trim().length < 3) { error.value = 'Indicá un motivo de rechazo de al menos 3 caracteres.'; return; }
 53	  busy.value = true; error.value = ''; notice.value = '';
 54	  try {
 55	    await session.apiRequest(`/admin/listings/${encodeURIComponent(item.id)}/review`, {
 56	      method: 'POST', body: JSON.stringify(action === 'reject' ? { action, reason: reason.value.trim() } : { action }),
 57	    });
 58	    notice.value = action === 'approve' ? 'Publicación aprobada. Queda pendiente de publicación.' : 'Publicación rechazada con motivo.';
 59	    reason.value = ''; await load();
 60	  } catch (e) {
 61	    error.value = e instanceof ApiError && e.status === 409 ? 'Otra sesión ya revisó esta publicación. Actualizá la cola.' : e instanceof Error ? e.message : 'No se pudo confirmar la revisión.';
 62	  } finally { busy.value = false; }
 63	}
 64	async function publish() {
 65	  const item = selected(); if (!item || busy.value) return;
 66	  busy.value = true; error.value = ''; notice.value = '';
 67	  try {
 68	    await session.apiRequest(`/admin/listings/${encodeURIComponent(item.id)}/publish`, { method: 'POST' });
 69	    notice.value = 'Publicación visible en el catálogo.'; await load();
 70	  } catch (e) { error.value = e instanceof Error ? e.message : 'No se pudo publicar la ficha.'; }
 71	  finally { busy.value = false; }
 72	}
 73	onMounted(load);
 74	</script>
