102	        </div>
103	        <div v-else-if="selected()!.status === 'APPROVED' && selected()!.publicationStatus === 'UNPUBLISHED'" class="admin-review-actions">
104	          <p>La aprobación está registrada. La ficha sigue oculta hasta que la publiques.</p>
105	          <button :disabled="busy || selected()!.requiresMediaRecovery" @click="publish">{{ busy ? 'Publicando…' : 'Publicar en catálogo' }}</button>
106	        </div>
107	      </article>
108	    </div>
109	    <button v-if="!loading && nextCursor" class="secondary" :disabled="busy" @click="loadMore">Cargar más publicaciones</button>
110	    <section class="card admin-audit"><h3>Actividad reciente</h3><ul><li v-for="entry in audit" :key="entry.id">
111	      {{ entry.action === 'LISTING_APPROVED' ? 'Aprobó' : entry.action === 'LISTING_PUBLISHED' ? 'Publicó' : entry.action === 'LISTING_REJECTED' ? 'Rechazó' : entry.action }} — {{ entry.actor.email }} — {{ entry.targetOwner?.email ?? (entry.entityType + (entry.entityId ? ' ' + entry.entityId : '')) }} — {{ entry.reason ?? (entry.action === 'LISTING_PUBLISHED' ? 'Publicación visible en el catálogo' : entry.action === 'LISTING_APPROVED' ? 'Publicación aprobada' : 'Evento registrado') }}
112	    </li></ul><p v-if="!audit.length">Todavía no hay decisiones registradas.</p></section>
113	  </section>
